select
beautician.*
from beautician beautician

    and beautician.id = #{id}
    and beautician.job_id = #{jobId}
    and beautician.name like concat('%',#{name},'%')
    and beautician.username = #{username}
    and beautician.password = #{password}
    and beautician.sex = #{sex}
    and beautician.age = #{age}
    and beautician.avatar = #{avatar}
    and beautician.info = #{info}
    and beautician.status = #{status}
    and beautician.create_time = #{createTime}
    and beautician.recomment = #{recomment}


    limit #{current},#{pageSize}

